								<td align="left" valign="middle">
									<b><a href="http://masslinemedia.com/smf/index.php?topic=2814.msg32865#msg32865">&quot;Put Away Your Flags&quot; - Howard Zinn, 7/4/07</a></b>
									<div class="smalltext">&#171; <b> on:</b> July 04, 2007, 12:34:33 pm &#187;</div></td>
								<td align="right" valign="bottom" height="20" nowrap="nowrap" style="font-size: smaller;">
								</td>
